import{_ as e,o as r,c as t,a2 as p}from"./chunks/framework.F7eQ-ohH.js";const n="/bzygq/assets/6dabeec08d5b4228879da911263aca2a.NW3akPAV.png",o="/bzygq/assets/bae2bea7c04c4a77b7608d66af063186.C9oy0l4u.png",s="/bzygq/assets/20f3b8a05a80492b8640c2f305926a89.Cs50dpni.png",i="/bzygq/assets/ccf50547c6f54b41a4a16ad4b54d3eb7.BfNoDuSn.png",u=JSON.parse('{"title":"召回优化、混合检索与Rerank","description":"","frontmatter":{},"headers":[],"relativePath":"AI应用开发/三、RAG教程/召回优化、混合检索与Rerank.md","filePath":"AI应用开发/三、RAG教程/召回优化、混合检索与Rerank.md","lastUpdated":1788928265000}'),l={name:"AI应用开发/三、RAG教程/召回优化、混合检索与Rerank.md"};function d(h,a,c,R,k,_){return r(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="召回优化、混合检索与rerank" tabindex="-1">召回优化、混合检索与Rerank <a class="header-anchor" href="#召回优化、混合检索与rerank" aria-label="Permalink to &quot;召回优化、混合检索与Rerank&quot;">​</a></h1><p><strong>召回优化、混合检索与Rerank</strong></p><p>RAG 系统回答得准不准，第一道关不是模型生成，而是检索召回。所谓召回，就是系统从知识库中找出与用户问题相关的候选 Chunk。召回阶段找不到正确依据，后面的大模型只能在错误材料或缺失材料上组织语言，答案自然很难稳定。</p><p>基础向量检索在 Demo 里经常看起来够用，因为问题简单、文档少、表达标准。但真实企业知识库会遇到更复杂的情况：用户提问短而口语化，业务术语和制度编号很多，同义词和简称混用，问题还可能跨多个制度或多个业务系统。单一向量检索很容易漏召回、错召回或把正确片段排到后面。</p><p>所以，召回优化的目标不是“召回越多越好”，而是在覆盖率和准确率之间取得平衡。前置召回要尽可能覆盖正确材料，后续重排和压缩要把真正有用的证据放进 Prompt，减少无关片段对模型的干扰。</p><h1 id="一、召回优化到底在优化什么" tabindex="-1">一、召回优化到底在优化什么 <a class="header-anchor" href="#一、召回优化到底在优化什么" aria-label="Permalink to &quot;一、召回优化到底在优化什么&quot;">​</a></h1><p>召回优化要解决的是“正确依据能不能被找到、能不能排在前面、能不能进入上下文”。比如用户问“试用期员工请假会不会影响转正”，系统需要从员工手册、考勤制度、转正规则中找到相关条款。如果只召回了普通请假流程，没有召回转正评估规则，模型就可能答得很顺，但依据是不完整的。</p><p><img src="'+n+'" alt=""></p><p>真实项目里的召回问题通常有几类。用户问题太短，系统不知道具体场景；问题表达太口语，字面词和制度原文对不上；专有名词、编号、接口名不能只靠语义相似猜；多跳问题需要同时召回多个材料；Chunk 切分和 Metadata 过滤也可能让正确依据被切断或被过滤掉。召回优化就是围绕这些问题逐层补强。</p><p>排查时要先看召回结果，而不是先改 Prompt。只要正确 Chunk 没有进入候选集合，后面再好的 Rerank 和大模型都无法凭空补回依据。</p><p>Rewrite：把用户原话改成适合检索的问题</p><p>用户输入通常不是为检索系统准备的。真实问法可能是“退款怎么弄”“票没了还能报吗”“转正会卡请假吗”。这些问题对人来说能理解，但对检索系统来说信息太少。Query Rewrite 的作用，是在不改变用户意图的前提下，把口语化、简略化、指代不清的问题改写成更完整的检索表达。</p><p><img src="'+o+'" alt=""></p><p>查询重写可以由规则、同义词词典、业务词库或大模型完成。简单场景下，规则和词典就能解决常见简称、同义词和术语映射；复杂场景下，可以让大模型结合会话上下文补全实体、业务场景和约束条件。关键点是：重写不是为了让问题变漂亮，而是让检索系统更容易命中正确材料。</p><p>Multi Query 则是在重写基础上进一步扩展。系统为同一个用户问题生成多个检索表达，从不同角度召回候选片段，再合并结果。它能减少单一表达带来的偏差，尤其适合用户表达模糊、知识库里说法不统一、同义词较多的场景。但多路查询也会带来更多候选噪声，所以后面必须配合去重、融合和 Rerank。</p><p>Search：让向量检索和关键词检索各做擅长的事</p><p>向量检索擅长处理语义相似，关键词检索擅长处理精确匹配。企业知识库里两类问题都会出现，所以混合检索通常比单一路径更稳。</p><p><img src="'+s+'" alt=""></p><p>向量检索适合用户口语化提问、同义表达和语义相关内容。例如“票据丢了还能报销吗”可以召回“发票遗失处理流程”。关键词检索适合制度编号、接口名、产品型号、错误码和原文术语。例如“BGP-2025-07 接口超时”这类问题，如果只靠向量相似，可能找不到精确接口文档；加入 BM25 或关键词检索后，命中关键编号的概率会更高。</p><p>混合检索的难点不在于同时跑两种检索，而在于结果融合。向量召回和关键词召回的分数体系不同，不能简单把分数直接相加。工程上常见做法是先分别召回，再按来源、排名、关键词命中、向量相似度和业务权重做融合，最后统一去重。融合策略做得好，能兼顾语义覆盖和精确命中；融合策略粗糙，则可能把大量重复或低质量片段送进后续环节。</p><h1 id="四、rerank-把候选结果重新排一遍" tabindex="-1">四、Rerank：把候选结果重新排一遍 <a class="header-anchor" href="#四、rerank-把候选结果重新排一遍" aria-label="Permalink to &quot;四、Rerank：把候选结果重新排一遍&quot;">​</a></h1><p>初步召回通常追求覆盖，所以会返回较多候选片段，例如 Top-20 或 Top-50。但“被召回”不等于“最适合放进 Prompt”。向量检索和关键词检索更像粗筛，它们能快速找出可能相关的材料，却不一定能精确判断哪个片段最能回答问题。</p><p><img src="'+i+'" alt=""></p><p>Rerank 的作用，是用更精细的模型重新判断用户问题和候选片段的相关性。常见方式包括 Cross Encoder、LLM Rerank 和规则加权。Cross Encoder 会把问题和文档片段一起输入模型，直接计算相关性得分，准确性通常比单纯向量相似更好，但计算成本更高。LLM Rerank 更灵活，可以结合复杂语义判断，但成本、延迟和稳定性要评估。规则加权适合补充工程信号，例如标题命中、文档来源、更新时间、权限范围和业务优先级。</p><p>实际项目里经常采用“先多召回，再精重排”的思路。前面用向量、关键词和 Multi Query 尽量覆盖候选，后面用 Rerank 把 Top-20 压缩成 Top-3 或 Top-5。这样既避免漏掉关键材料，又能控制最终上下文的噪声。</p><h1 id="五、上下文压缩-材料不是越多越好" tabindex="-1">五、上下文压缩：材料不是越多越好 <a class="header-anchor" href="#五、上下文压缩-材料不是越多越好" aria-label="Permalink to &quot;五、上下文压缩：材料不是越多越好&quot;">​</a></h1><p>很多 RAG 新手会以为召回越多越安全。实际上，上下文窗口不是资料仓库。无关片段越多，模型越容易被干扰；重复片段越多，Prompt 信息密度越低；长材料越多，成本和延迟越高。RAG 要给模型的不是“很多材料”，而是“足够、相关、可追溯的证据”。</p><p>上下文压缩通常发生在 Rerank 之后。系统可以只保留与问题直接相关的段落，删除候选片段里的无关句子，合并重复材料，或者把长材料压缩成更短的依据摘要。压缩时要小心，不能为了短而丢掉关键条件、例外说明和适用范围。对于制度问答，例外条款经常比主流程更重要。</p><p>去重也很关键。多路查询、overlap 和相似 Chunk 很容易召回重复内容。如果不去重，Prompt 里会出现很多看似不同、实则相近的片段，模型得到的有效信息并没有增加，反而挤占了真正关键材料的位置。</p><h1 id="六、召回优化的完整链路" tabindex="-1">六、召回优化的完整链路 <a class="header-anchor" href="#六、召回优化的完整链路" aria-label="Permalink to &quot;六、召回优化的完整链路&quot;">​</a></h1><p>一个比较成熟的 RAG 检索链路，通常会把查询改写、多路查询、混合检索、结果融合、Rerank 和上下文压缩串起来。不是每个项目一开始都要做满，但你要知道每个环节解决什么问题。</p><p>用户问题进入系统后，先通过 Query Rewrite 补全表达，再根据需要生成多个查询版本。每个查询可以同时走向量检索和关键词检索，并结合 Metadata 做权限、版本和类别过滤。召回结果合并去重后进入 Rerank，挑出最相关的 Top-N，再做必要的上下文压缩，最后交给 Prompt 构建。</p><p>这个链路的核心思想是分层处理：召回层负责“尽量别漏”，重排层负责“把重要的排前面”，压缩层负责“减少噪声”，Prompt 层负责“约束模型基于材料回答”。如果把所有压力都交给大模型，系统很容易在复杂问题上失控。</p><h1 id="七、怎么判断召回优化真的有效" tabindex="-1">七、怎么判断召回优化真的有效 <a class="header-anchor" href="#七、怎么判断召回优化真的有效" aria-label="Permalink to &quot;七、怎么判断召回优化真的有效&quot;">​</a></h1><p>召回优化不能只靠主观感觉。更好的方式是建立一组真实问题集，每个问题标注应该命中的文档、章节或 Chunk，然后观察优化前后正确依据是否被召回、排名是否提前、进入 Prompt 的材料是否更干净。</p><p>常看的指标包括 Recall@K、MRR、NDCG 和人工评测。Recall@K 关注正确材料是否出现在前 K 个候选里；MRR 关注第一个正确结果排在多靠前；NDCG 更适合多个相关结果有不同重要程度的情况。对于初学者，先把“正确依据是否进入 Top-K”和“是否进入最终 Prompt”看清楚，就已经能定位大部分问题。</p><p>同时要记录线上日志：用户问题、重写后的查询、多路查询版本、向量召回结果、关键词召回结果、融合后候选、Rerank 分数、最终上下文和模型答案。没有这些日志，就无法判断问题出在召回、融合、重排、压缩还是生成。</p><h1 id="八、面试表达模板" tabindex="-1">八、面试表达模板 <a class="header-anchor" href="#八、面试表达模板" aria-label="Permalink to &quot;八、面试表达模板&quot;">​</a></h1><p>面试中可以这样回答：</p><table tabindex="0"><thead><tr><th>Plain Text如果 RAG 召回不准，我会先看检索结果，而不是直接换大模型。优化上会分几层处理：第一是 Query Rewrite，把用户口语化问题改写成更适合检索的表达；第二是 Multi Query，从多个角度召回候选；第三是 Hybrid Search，把向量检索和 BM25 关键词检索结合；第四是结果融合和去重，避免重复片段占满上下文；第五是 Rerank，把初步召回的 Top-K 候选重新排序；最后再做上下文压缩，把最相关的证据交给大模型。</th></tr></thead></table><p>如果被追问“为什么要 Rerank”，可以补充：</p><table tabindex="0"><thead><tr><th>Plain Text向量检索适合快速召回候选，但排序不一定精确。Rerank 会用更细的相关性模型重新判断问题和候选文档的匹配程度，通常可以把 Top-20 候选压缩成 Top-3 或 Top-5，提高最终输入给大模型的材料质量，减少无关上下文对答案的干扰。</th></tr></thead></table><p>召回优化讲清楚之后，还要补最后一块：怎么判断 RAG 系统真的变好了，以及项目里怎么表达。</p>',43)])])}const m=e(l,[["render",d]]);export{u as __pageData,m as default};
